from datetime import datetime, timezone, timedelta

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since the Unix epoch (1970-01-01 00:00:00 UTC)
    :param tz: Timezone string or tzinfo object (default is UTC)
    :return: datetime.datetime object representing the hydrated time
    """
    if not isinstance(nanoseconds, int) or nanoseconds < 0:
        raise ValueError("nanoseconds must be a non-negative integer")

    if tz is None:
        tz = timezone.utc

    try:
        if isinstance(tz, str):
            tz = timezone.strptime(tz, "%Z")

        timestamp = nanoseconds / 1e9
        dt = datetime.fromtimestamp(timestamp, tz)
        return dt
    except (ValueError, OSError) as e:
        raise ValueError(f"Invalid timezone '{tz}'") from e

