def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: str
    :return: int
    """
    if not isinstance(value, str):
        raise ValueError("Input value must be a string representing time.")

    time_parts = value.split(':')
    if len(time_parts) != 3:
        raise ValueError("Invalid time format. Expected 'HH:MM:SS'.")

    try:
        hours, minutes, seconds = map(int, time_parts)
    except ValueError:
        raise ValueError("Invalid time format. Expected 'HH:MM:SS' with integer values.")

    if hours < 0 or hours > 23 or minutes < 0 or minutes > 59 or seconds < 0 or seconds > 59:
        raise ValueError("Invalid time values. Hours must be between 0 and 23, minutes and seconds must be between 0 and 59.")

    return hours * 3600 + minutes * 60 + seconds

