def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx):
            if metadata is not None:
                tx.metadata = metadata
            if timeout is not None:
                import time
                start_time = time.time()
                result = func(tx)
                elapsed_time = time.time() - start_time
                if elapsed_time > timeout:
                    raise TimeoutError("Transaction timed out after {:.2f} seconds".format(elapsed_time))
                return result
            else:
                return func(tx)
        return wrapper
    return decorator

