def round_half_to_even(n):
    """
    Rounds a number to the nearest integer using "round half to even" (also known as "bankers' rounding").

    Parameters:
    n (float or int): The number to round.

    Returns:
    int: The rounded number.

    This function rounds half-way cases to the nearest even number, following the IEEE 754 standard.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    fractional_part = n - int(n)
    if abs(fractional_part - 0.5) < 1e-9:
        return int(n) + (int(n) % 2)
    else:
        return round(n)
