import random

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not seq:
        return []

    result = list(seq)
    for i in range(len(result) - 1, 0, -1):
        j = random.randint(0, i)
        result[i], result[j] = result[j], result[i]
    return result

