def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import sys
    import os

    if sys.platform != 'win32':
        return cmd

    new_cmd = []
    for part in cmd:
        if part.startswith('#!'):
            # Fix shebang for windows
            full_path = os.path.abspath(part)
            new_cmd.append(full_path)
        else:
            new_cmd.append(part)

    return tuple(new_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        raise ValueError("Command tuple must not be empty")

    first_arg, *rest = cmd

    if first_arg.startswith("#!"):
        # Normalize shebang if it contains backslashes
        first_arg = first_arg.replace("\\", "/")

    return (first_arg,) + tuple(rest)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    # Normalize the command by handling issues related to Windows shell parsing
    # For simplicity, let's assume the command is always a tuple of strings
    if not cmd or not cmd[0]:
        raise ValueError("Command must not be empty")

    # Check if the command contains a shebang and handle it
    normalized_cmd = list(cmd)
    if normalized_cmd[0].startswith("#!"):
        normalized_cmd[0] = normalized_cmd[0].replace("\\", "/")

    return tuple(normalized_cmd)

