class ExceptionFormatter:
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        if not isinstance(e, Exception):
            raise ValueError("The provided input is not an exception instance.")

        def format_stack(stack, level):
            if level > max_level:
                return "..."
            return [f"{frame.filename}:{frame.lineno}:{frame.name}" for frame in stack[:level]]

        def format_path(path, level):
            if level > max_path_level:
                return "..."
            return [f"{module_name}:{function_name}" for module_name, function_name in path[:level]]

        def format_exception(e, level=0):
            stack = e.__traceback__
            path = cls.get_exception_path(e)
            return f"{type(e).__name__}: {e}\nStack: {format_stack(stack, level)}\nPath: {format_path(path, level)}"

        return format_exception(e)

    @staticmethod
    def get_exception_path(e):
        from types import TracebackType
        path = []
        tb: TracebackType = e.__traceback__
        while tb:
            path.append((tb.tb_frame.f_globals["__name__"], tb.tb_frame.f_code.co_name))
            tb = tb.tb_next
        return path

