                if max_path_level > 0:
                    file_path = file_path.split('/')[-max_path_level:]
                    file_path = '/'.join(file_path)
                line_no = frame.lineno
                co_name = frame.code_context[0].strip()
                return f"{file_path}:{line_no}: {co_name}"
            except Exception:
                return "Unknown frame"

        def format_traceback(tback, max_level):
            level = 0
            frames = []
            while tback is not None and level < max_level:
                frames.append(format_traceback_frame(tback, max_path_level))
                tback = tback.tb_next
                level += 1
            return ' -> '.join(frames)

