def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent

    :param classes: List of strings representing base classes
    :return: List of strings representing the minimal equivalent of base classes
    """
    if not classes:
        return []

    # Create a dictionary to store the dependencies for each class
    dependencies = {cls: set() for cls in classes}

    # Populate the dependencies dictionary
    for cls in classes:
        if cls in classes:
            raise ValueError(f"Base class '{cls}' is not in the list of classes")
        for dependency in classes[cls].split(','):
            dependency = dependency.strip()
            if dependency and dependency not in classes:
                raise ValueError(f"Dependency '{dependency}' of base class '{cls}' is not in the list of classes")
            dependencies[cls].add(dependency)

    # Sort the classes based on their dependencies
    minimal_classes = []
    while classes:
        independent_classes = [cls for cls in classes if not dependencies[cls]]
        if not independent_classes:
            raise ValueError("Circular dependency detected")
        minimal_classes.extend(independent_classes)
        classes = [cls for cls in classes if cls not in independent_classes]
        for cls in classes:
            dependencies[cls] -= set(independent_classes)

    return minimal_classes

