    for i in range(len(bins)):
        bin_width = edges[i + 1] - edges[i]
        integral_value += bins[i] * bin_width

    return integral_value

def integral(bins, edges):
    if not (isinstance(bins, (list, tuple)) and isinstance(edges, (list, tuple))):
        raise ValueError("bins and edges must be lists or tuples")

    if len(bins) != len(edges) - 1:
        raise ValueError("bins and edges must have consistent lengths")

    if any(edge <= 0 for edge in edges):
        raise ValueError("all elements in edges must be positive")

    if any(previous >= current for previous, current in zip(edges, edges[1:])):
        raise ValueError("edges must be in strictly increasing order")

    result = 0.0
    for i in range(len(bins)):
        width = edges[i + 1] - edges[i]
        result += bins[i] * width

    return result
