    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, Mapping):
        param_style = 'named'
    elif isinstance(params, Sequence):
        param_style = 'ordinal'
    else:
        raise ValueError("params must be a dict or a sequence")

    formatted_sql = sql

    if param_style == 'named':
        param_dict = cast(Dict[Union[str, int], Any], params)
        placeholder_pattern = re.compile(r':([a-zA-Z_]\w*)')
        out_params = {}
        for match in placeholder_pattern.finditer(sql):
            param_name = match.group(1)
            if param_name in param_dict:
                placeholder = match.group(0)
                formatted_sql = formatted_sql.replace(placeholder, str(param_dict[param_name]))
                out_params[param_name] = param_dict[param_name]
            else:
                raise KeyError(f"Parameter '{param_name}' not found in params")

    elif param_style == 'ordinal':
        param_sequence = cast(Sequence[Any], params)
        placeholder_pattern = re.compile(r'\?')
        out_params = []
        for i, match in enumerate(placeholder_pattern.finditer(sql)):
            if i < len(param_sequence):
                placeholder = match.group(0)
                value = param_sequence[i]
                formatted_sql = formatted_sql.replace(placeholder, str(value))
                out_params.append(value)
            else:
                raise IndexError("Not enough parameters provided")

    return formatted_sql, out_params

