def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.
    *many_params* (:class:`~collections.abc.Iterable`) contains each set of in-style parameters (*params*).

    Returns a :class:`tuple` containing:
        - The formatted SQL query (:class:`str` or :class:`bytes`).
        - A :class:`list` containing each set of converted out-style parameters (:class:`dict` or :class:`list`).
    """
    if not isinstance(many_params, (list, tuple)):
        raise TypeError("many_params must be a list or tuple")

    out_params = []
    for params in many_params:
        if isinstance(params, dict):
            formatted_params = {f":{key}": value for key, value in params.items()}
        elif isinstance(params, Sequence):
            formatted_params = [None] * len(params)
        else:
            raise TypeError("params must be a dictionary or a sequence")

        out_params.append(formatted_params)

    formatted_sql = sql
    if isinstance(sql, str):
        formatted_sql = formatted_sql.replace("?", ":?")

    return formatted_sql, out_params

