def _group_files_by_xml_filename(xml_filename, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    from os.path import basename
    from xml.etree.ElementTree import parse
    from collections import defaultdict

    def get_xml_root(xml_file):
        try:
            return parse(xml_file).getroot()
        except Exception as e:
            print(f"Error parsing XML file {xml_file}: {e}")
            return None

    def get_xml_basename(xml_file):
        return basename(xml_file, '.xml')

    xml_basename_to_files = defaultdict(list)

    for file in files:
        if file.endswith('.xml'):
            basename = get_xml_basename(file)
            if basename:
                root = get_xml_root(file)
                if root is not None:
                    xml_basename_to_files[basename].append(file)

    return dict(xml_basename_to_files)

