    # Walk through the folder and handle each file
    for root, _, files in os.walk(folder):
        for file in files:
            # Check if the file is an XML file
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                xml_basename = os.path.splitext(file)[0]

                # Parse the XML file
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()

                    # Add the file data to the dictionary
                    if xml_basename not in package_data:
                        package_data[xml_basename] = []
                    package_data[xml_basename].append(root_element)
                except ET.ParseError:
                    print(f"Failed to parse XML file: {file_path}")

