def _eval_file(prefix, file_folder):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    try:
        if file_folder.endswith('asset'):
            file_type = 'asset'
        elif file_folder.endswith('rendition'):
            file_type = 'rendition'
        else:
            raise ValueError("Invalid file folder")

        package_info = {
            'type': file_type,
            'address': file_folder
        }

        return package_info
    except Exception as e:
        return {'error': str(e)}

