def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            data = {}
            for zip_info in zip_ref.infolist():
                if zip_info.filename.endswith('.xml'):
                    with zip_ref.open(zip_info) as xml_file:
                        xml_content = xml_file.read()
                        root = ET.fromstring(xml_content)
                        xml_basename = zip_info.filename[:-4]
                        if xml_basename in data:
                            data[xml_basename].append(root)
                        else:
                            data[xml_basename] = [root]
            return data
    except zipfile.BadZipFile:
        print(f"Error: The file {zip_path} is not a valid zip file.")
        return {}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {}

