class HookRegistry:
    def __init__(self):
        self.handlers = {}

    def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (str): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified hook.

        """
        def decorator(func):
            if hook not in self.handlers:
                self.handlers[hook] = []
            self.handlers[hook].append(func)
            return func
        return decorator

# Example usage:
hook_registry = HookRegistry()

@hook_registry.on('event1')
def handler1():
    print("Handler 1 for event1")

@hook_registry.on('event2')
def handler2():
    print("Handler 2 for event2")

def trigger_event(hook):
    if hook in hook_registry.handlers:
        for handler in hook_registry.handlers[hook]:
            handler()

