def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Get the list of all actions in the parser
    actions = parser._actions

    # Extract the flags from each action
    flags = []
    for action in actions:
        if action._nargs == 0:
            flags.append(f'-{action.option_strings[0][1:]}')
        else:
            for option in action.option_strings:
                flags.append(f'-{option[1:]}')

    # Join the flags into a space-separated string
    return ' '.join(flags)

