from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if not (0 <= number < len(alphabet)):
        raise ValueError(f"Number {number} is out of the valid range for the given alphabet")
    if padding is not None and not (0 <= padding <= number):
        raise ValueError(f"Padding {padding} is out of the valid range for the given number")

    result = []
    while number > 0:
        result.append(alphabet[number % len(alphabet)])
