from pathlib import Path, PosixPath
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not (archive_path and Path(archive_path).exists()):
        raise ValueError(f"Archive path '{archive_path}' does not exist.")

    tmp_path = Path(tmp_path)
    if not tmp_path.exists():
        tmp_path.mkdir(parents=True, exist_ok=True)

    if not filename:
        filename = Path(archive_path).name

    extract_cmd = [
        'tar', '-xzf', archive_path, '-C', tmp_path
    ]
    try:
        subprocess.run(extract_cmd, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")

    repo_dir = tmp_path / filename.strip('.tar.gz')  # Assuming the archive is a .tar.gz file
    if not repo_dir.exists():
        raise FileNotFoundError(f"Extracted repo directory '{repo_dir}' does not exist.")

    repo_url = str(repo_dir.resolve())
    return repo_url

