def addignored(ignored):
    try:
        # Run the 'git ls-files -i --exclude-standard' command to get the file names of ignored files
        result = subprocess.run(['git', 'ls-files', '-i', '--exclude-standard'],stdout=subprocess.PIPE,stderr=subprocess.PIPE, text=True)

        # Check if the command was successful
        if result.returncode != 0:
            raise Exception(f"Error running git command: {result.stderr}")

        # Split the output into a list of filenames
        files = result.stdout.strip().splitlines()

        # Filter the list to include only the ignored files
        ignored_files = [file for file in files if file in ignored]

        # Sort the ignored files
        ignored_files.sort()

        # Return the ignored files as a single string with each filename separated by a comma
        return ','.join(ignored_files)

    except Exception as e:
        # Handle any exceptions that may occur
        return str(e)

