    """Call the given command(s)."""
    if not commands or not args:
        raise ValueError("Commands and args must be provided")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string")

    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary")

    command = [commands] + args

    if verbose:
        print(f"Running command: {command}")

    try:
        if hide_stderr:
            output = subprocess.run(command, cwd=cwd, env=env, check=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
        else:
            output = subprocess.run(command, cwd=cwd, env=env, check=True, text=True)
        return output.stdout
    except subprocess.CalledProcessError as e:
        if hide_stderr:
            raise RuntimeError(f"Command failed with output: {e.stdout}") from e
        else:
            raise RuntimeError(f"Command failed with output: {e.stderr}") from e
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}") from e

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]

    cmd = [commands[0]] + args
    try:
        if hide_stderr:
            result = subprocess.run(cmd, cwd=cwd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, env=env)
        else:
            result = subprocess.run(cmd, cwd=cwd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)

        if result.returncode != 0:
            if not hide_stderr:
                print("Error:", result.stderr.decode())
            return None

        if verbose:
            print("Output:", result.stdout.decode())

        return result.stdout.decode()
    except Exception as e:
        print("An error occurred:", str(e))
        return None

