from typing import Optional, Set

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None
) -> Set[Node]:
    if roots is None:
        roots = set()

    # Find all nodes that are the subject of the given property
    children = {s for s, p, o in graph.triples((None, prop, None))}

    # Find all nodes that are the object of the given property
    parents = {o for s, p, o in graph.triples((None, prop, None))}

    # Roots are the nodes that are subjects but not objects
    new_roots = children - parents

    # Add new roots to the set of roots
    roots.update(new_roots)

    if not new_roots:
        return roots

    # Recursively find roots for each new root
    return find_roots(graph, prop, roots)

