from datetime import datetime, timezone, timedelta

class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        # Convert ticks to seconds
        total_seconds = ticks / 1e9

        # Create a naive datetime object for midnight
        midnight = datetime(1970, 1, 1) + timedelta(seconds=total_seconds)

        if tz:
            # Localize the datetime object to the specified timezone
            midnight = tz.localize(midnight)

        # Convert to a time object
        time_obj = midnight.time()

        return cls(time_obj)

