def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not hist or not isinstance(hist, dict):
        raise ValueError("Invalid histogram input")

    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid get_coordinate value")

    if len(field_names) != 2:
        raise ValueError("Invalid field_names length")

    if scale is not None and not isinstance(scale, (int, float)):
        raise ValueError("Invalid scale value")

    graph_data = []
    for bin_label, bin_content in hist.items():
        if get_coordinate == "left":
            x_coordinate = bin_label - 0.5
        elif get_coordinate == "right":
            x_coordinate = bin_label + 0.5
        elif get_coordinate == "middle":
            x_coordinate = bin_label

        if make_value(bin_content) is not None:
            y_value = make_value(bin_content)
            graph_data.append((x_coordinate, y_value))

    return dict(zip(field_names, zip(*graph_data))) if graph_data else {}

def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        def make_value(bin_):
            return bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be one of 'left', 'right', or 'middle'")

    if len(field_names) != 2:
        raise ValueError("field_names must contain exactly two elements")

    points = []

    for i, bin_ in enumerate(hist.bins):
        if get_coordinate == "left":
            x = hist.x_edges[i]
        elif get_coordinate == "right":
            x = hist.x_edges[i + 1]
        elif get_coordinate == "middle":
            x = 0.5 * (hist.x_edges[i] + hist.x_edges[i + 1])

        y = make_value(bin_)

        points.append((x, y))

    graph = {
        "field_names": field_names,
        "points": points,
        "scale": hist.scale if scale else None
    }

    return graph

