def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not make_value:
        make_value = lambda bin_: bin_.content

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("Invalid get_coordinate value")

    if not all(isinstance(name, str) for name in field_names):
        raise ValueError("All field_names must be strings")

    if len(field_names) != 1:
        raise ValueError("field_names must have length 1")

    points = []
    for bin_ in hist:
        value = make_value(bin_)
        if get_coordinate == "left":
            coord = bin_.edges[0]
        elif get_coordinate == "right":
            coord = bin_.edges[1]
        else:  # get_coordinate == "middle"
            coord = (bin_.edges[0] + bin_.edges[1]) / 2
        points.append((coord, value))

    # Convert points to the desired format
    graph = {field_names[0]: [], f"y_{field_names[0]}": []}
    for point in points:
        graph[field_names[0]].append(point[0])
