def isoparse(dt_str: str) -> datetime:
    """
    Parse an ISO-8601 datetime string into a datetime.datetime.

    :param dt_str: A string containing only an ISO-8601 datetime string
    :return: Returns a datetime.datetime representing the string.
    """
    try:
        # Handle time zone offset formats
        if 'Z' in dt_str:
            dt_str = dt_str.replace('Z', '+00:00')
        elif ' ' in dt_str:
            dt_str = dt_str.replace(' ', 'T')
        if ':' in dt_str:
            dt_str = dt_str.replace(',', '.')

        # Parse the date and time components
        if 'T' in dt_str:
            date_str, time_str = dt_str.split('T')
        else:
            date_str = dt_str
            time_str = ''

        # Parse the date component
        if '-' in date_str:
            if date_str.count('-') == 2:
                year, month, day = map(int, date_str.split('-'))
                time_str = time_str or '00:00:00'
            elif date_str.count('-') == 1:
                year, month = map(int, date_str.split('-'))
                day = 1
                time_str = time_str or '00:00:00'
        else:
            if len(date_str) == 4:
                year = int(date_str)
                month = 1
                day = 1
                time_str = time_str or '00:00:00'
            elif len(date_str) == 6:
                year = int(date_str[:4])
                month = int(date_str[4:6])
                day = 1
                time_str = time_str or '00:00:00'
            elif len(date_str) == 8:
                year = int(date_str[:4])
                month = int(date_str[4:6])
                day = int(date_str[6:8])
                time_str = time_str or '00:00:00'

        # Parse the time component
        if ':' in time_str:
            hours, minutes, seconds = map(int, time_str.split(':'))
        else:
            hours = int(time_str)
            minutes = 0
            seconds = 0

        # Parse the optional decimal fraction
        if '.' in time_str:
            tz_offset_str, fraction = time_str.rsplit('.', 1)
            tz_offset = timedelta(seconds=int(fraction) / (10 ** len(fraction)))
        else:
            tz_offset = timedelta(0)

        # Combine the components
        naive_dt = datetime(year, month, day, hours, minutes, seconds)
        if tz_offset == timedelta(0):
            dt = naive_dt.replace(tzinfo=tzutc())
        else:
            dt = naive_dt.replace(tzinfo=tzoffset(None, int(tz_offset.total_seconds())))

        return dt

    except Exception as e:
        raise ValueError(f"Invalid ISO-8601 datetime string: {dt_str}") from e

