class DateParser:
    def parse(self, timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
        if not isinstance(timestr, str):
            raise TypeError("Non-string or character stream input")

        if tzinfos is not None and not isinstance(tzinfos, (dict, callable)):
            raise TypeError("Invalid tzinfos type")

        try:
            naive_dt = _parse(timestr, **kwargs)
        except Exception as e:
            raise ParserError("Invalid or unknown string format") from e

        if ignoretz:
            return naive_dt.replace(tzinfo=None)

        if tzinfos is not None and naive_dt.tzinfo is not None:
            tzinfo = tzinfos.get(naive_dt.tzinfo.tzname(), naive_dt.tzinfo)
            if isinstance(tzinfo, int):
                tzinfo = tzoffset(naive_dt.tzinfo.tzname(), tzinfo)
            elif isinstance(tzinfo, str):
                tzinfo = gettz(tzinfo)
            naive_dt = naive_dt.replace(tzinfo=tzinfo)

        if default is not None:
            offset = (naive_dt - default).total_seconds()
            naive_dt = default + timedelta(seconds=offset)

        return naive_dt

