def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    result = text
    in_code_block = False

    i = 0
    while i < len(text):
        if text[i:i+3] == "<code>":
            in_code_block = True
            i += 5
        elif text[i:i+6] == "</code>":
            in_code_block = False
            i += 7
        elif not in_code_block and "<" in text[i:]:
            start = text.find("<", i)
            end = text.find(">", start)
            if end != -1:
                tag = text[start:end+1]
                if tag not in tags:
                    tags.add(tag)
                    if replacer:
                        result = result[:end+1] + str(replacer(tag)) + result[end+1:]
                    i = end + 2
                else:
                    i = end + 1
            else:
                break
        else:
            i += 1

    return tags, result

