def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Check if the document is in JSON format
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    try:
        # Check if the document is in XRD format
        root = ET.fromstring(document)
        namespace = {'xrd': 'http://info.yahoo.com/xrd'}
        subject = root.find('{http://info.yahoo.com/xrd}Subject', namespace).text
        links = []
        for link in root.findall('{http://info.yahoo.com/xrd}Link', namespace):
            rel = link.get('rel')
            href = link.get('href')
            links.append({'rel': rel, 'href': href})
        return {'subject': subject, 'links': links}
    except ET.ParseError:
        pass

    raise ValueError("Invalid(Webfinger): Neither XRD nor JSON was detected")

