import json
from bs4 import BeautifulSoup

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if document.startswith('{'):
        return parse_json_webfinger(document)
    else:
        return parse_xrd_webfinger(document)

def parse_json_webfinger(document: str) -> Dict:
    try:
        data = json.loads(document)
        if 'links' in data:
            return {link['rel']: link['href'] for link in data['links']}
        else:
            raise ValueError("Invalid JSON structure for webfinger")
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format for webfinger")

def parse_xrd_webfinger(document: str) -> Dict:
    try:
        soup = BeautifulSoup(document, 'xml')
        links = soup.find_all('Link')
        return {link['rel']: link['href'] for link in links}
    except Exception as e:
        raise ValueError(f"Invalid XRD format for webfinger: {e}")

