import os

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not os.path.exists(plugin_dir) or not os.path.isdir(plugin_dir):
        raise ValueError("Invalid plugin directory: {}".format(plugin_dir))

    flatten_dict = {}
    for root, _, files in os.walk(plugin_dir):
        for file in files:
            if file == "plugin_spec.json":
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    spec_data = f.read()
                    try:
                        import json
                        spec_dict = json.loads(spec_data)
                        flatten_dict = flatten_dict.update_recursively(flatten_dict, spec_dict)
                    except json.JSONDecodeError as e:
                        raise ValueError("Invalid JSON in plugin spec file: {}".format(e))
    return flatten_dict

def update_recursively(flat_dict, new_dict, parent_key=''):
    for key, value in new_dict.items():
        if isinstance(value, dict):
            update_recursively(flat_dict, value, f"{parent_key}.{key}" if parent_key else key)
        else:
            flat_dict[f"{parent_key}.{key}" if parent_key else key] = value
    return flat_dict

